<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {Database,LayoutDashboard,FolderOpen,Search,RefreshCw,ChevronRight,ArrowRight,ArrowUpRight,ShieldCheck,LockKeyhole,LoaderCircle,X,FileText,Table2,Layers3,CalendarClock,Server,Tag,Image,Download,Eye,AlertCircle,CheckCircle2,ChevronLeft,LayoutGrid,List} from 'lucide-vue-next';
import {appUrl} from '../lib/urls';
import {catalogAppCounts} from '../lib/catalog-counts';
import ResourceOverview from './ResourceOverview.vue';
import ResourceInspector from './ResourceInspector.vue';
import WidgetDataPreview from './WidgetDataPreview.vue';
import BiLiveViewer from './BiLiveViewer.vue';
import BiManualAction from './BiManualAction.vue';
import BiCredentialForm from './BiCredentialForm.vue';
import BiCredentialActions from './BiCredentialActions.vue';
import BiDeskForm from './BiDeskForm.vue';
import BiScheduleForm from './BiScheduleForm.vue';
import BiScheduleRun from './BiScheduleRun.vue';
import BiFlowWizardDialog from './BiFlowWizardDialog.vue';
import BiTablePresentationForm from './BiTablePresentationForm.vue';
type Item=Record<string,any>;
const scheduleCreator=ref(false);const scheduleDialog=ref<HTMLElement|null>(null);let scheduleReturnFocus:HTMLElement|null=null;
const flowWizardCreator=ref(false);
const credentialCreator=ref(false);const manualActionOpen=ref(false);
const deskCreator=ref('');const deskDialog=ref<HTMLElement|null>(null);let deskReturnFocus:HTMLElement|null=null;
const credentialDialog=ref<HTMLElement|null>(null);
const props=defineProps<{tenants:Item[];connected:boolean;userId:number;role:string;viewerContextUsed?:boolean;download?:(path:string,name:string,isCurrent:()=>boolean)=>Promise<void>;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{project:[id:string];connect:[];viewerSession:[];updated:[];notice:[message:string];helpBlocked:[blocked:boolean]}>();
const tenant=ref('');const snapshot=ref<Item|null>(null);const loading=ref(false);const error=ref('');const kind=ref('app');const search=ref('');const scope=ref('all');const desk=ref('');const tag=ref('');const page=ref(1);const selected=ref<Item|null>(null);const detail=ref<Item|null>(null);const detailLoading=ref(false);const detailError=ref('');const creating=ref(false);const dashboard=ref('');const image=ref('');const imageLoading=ref(false);const dataLoading=ref(false);const preview=ref<Item|null>(null);const tab=ref('overview');
watch([loading,selected,credentialCreator,deskCreator,scheduleCreator,flowWizardCreator],()=>emit('helpBlocked',Boolean(loading.value||selected.value||credentialCreator.value||deskCreator.value||scheduleCreator.value||flowWizardCreator.value)),{immediate:true,flush:'sync'});
const history=ref<Item[]>([]);const dialog=ref<HTMLElement|null>(null);
const layout=ref<'grid'|'list'>('grid');const resultsHeading=ref<HTMLElement|null>(null);
function readPreference(name:string){try{return localStorage.getItem('g-analise:'+name+':'+props.userId);}catch{return null;}}
function savePreference(name:string,value:string){try{localStorage.setItem('g-analise:'+name+':'+props.userId,value);}catch{}}
function chooseLayout(value:'grid'|'list'){layout.value=value;savePreference('catalog-view',value);}
async function changePage(value:number){page.value=value;await nextTick();resultsHeading.value?.scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});resultsHeading.value?.focus({preventScroll:true});}
let catalogQueue:Promise<void>=Promise.resolve();
let requestVersion=0;let detailVersion=0;let previewVersion=0;let returnFocus:HTMLElement|null=null;
const kinds=[{id:'app',label:'Aplicações',icon:LayoutDashboard},{id:'bi-desk',label:'Mesas de aplicações',icon:FolderOpen},{id:'dw-desk',label:'Mesas de dados',icon:Layers3},{id:'table',label:'Tabelas',icon:Table2},{id:'flow',label:'Fontes / ETL',icon:Database},{id:'schedule',label:'Agendas',icon:CalendarClock},{id:'agent',label:'Agentes',icon:Server},{id:'writeback',label:'Cadastros',icon:Table2},{id:'deck',label:'Decks',icon:FileText},{id:'presentation',label:'Apresentações',icon:Image},{id:'investigation',label:'Investigações',icon:Search},{id:'credential',label:'Conexões de dados',icon:LockKeyhole},{id:'variables',label:'Variáveis',icon:Tag}];
const rows=computed<Item[]>(()=>snapshot.value?.resources?.[kind.value]??[]);
const capability=computed(()=>snapshot.value?.capabilities?.[kind.value]);
const desks=computed<Item[]>(()=>snapshot.value?.resources?.[kind.value==='app'?'bi-desk':'dw-desk']??[]);
const deskNames=computed(()=>Object.fromEntries(desks.value.map(d=>[d.id,d.name])));
const filtered=computed(()=>rows.value.filter(row=>{const text=[row.name,row.description,row.ref,...(row.tags??[]),...(row.dashboards??[]).map((d:Item)=>d.name)].join(' ').toLocaleLowerCase('pt-BR');return(!search.value||text.includes(search.value.toLocaleLowerCase('pt-BR')))&&(scope.value==='all'||row.state===scope.value)&&(!desk.value||row.desk_id===desk.value)&&(!tag.value||row.tags.includes(tag.value));}));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/18)));const visible=computed(()=>filtered.value.slice((page.value-1)*18,page.value*18));
const appStats=computed(()=>catalogAppCounts(snapshot.value?.capabilities?.app,snapshot.value?.resources?.app));
const dashboardList=computed<Item[]>(()=>detail.value?.resource?.dashboards??[]);
const unavailable=computed(()=>Object.values(snapshot.value?.capabilities??{}).filter((c:any)=>c.status!=='available'&&c.status!=='not_loaded').length);
const widgets=computed<Item[]>(()=>preview.value?.data?.widgets??[]);
watch([search,scope,desk,tag,kind],()=>page.value=1);
watch(tenant,()=>{requestVersion++;close();search.value='';scope.value='all';desk.value='';tag.value='';snapshot.value=null;if(tenant.value){savePreference('tenant',tenant.value);if(props.viewerContextUsed){window.location.assign(appUrl('/app/catalog'));return;}load();}else{loading.value=false;error.value='';}});
watch(kind,()=>{if(tenant.value)load();});
watch(()=>props.connected,connected=>{if(!connected){requestVersion++;close();tenant.value='';snapshot.value=null;loading.value=false;error.value='';}else if(tenant.value)load();});
watch(()=>props.tenants,items=>{if(tenant.value&&!items.some(item=>String(item.id)===tenant.value))tenant.value='';});
watch(dashboard,()=>{previewVersion++;clearImage();preview.value=null;imageLoading.value=false;dataLoading.value=false;tab.value='overview';});
function selectKind(value:string,selectedScope='all'){kind.value=value;scope.value=selectedScope;desk.value='';tag.value='';}
function label(state:string){return ({draft:'Minha Mesa',published:'Publicado',active:'Ativo',inactive:'Inativo',available:'Disponível',access_denied:'Sem permissão',unavailable:'Indisponível'} as Record<string,string>)[state]??state;}
async function savedCredential(ref:string){const targetTenant=tenant.value;credentialCreator.value=false;close();const version=detailVersion;emit('updated');await load(true);if(tenant.value!==targetTenant||detailVersion!==version||selected.value)return;const row=snapshot.value?.resources?.credential?.find((item:Item)=>item.ref===ref);if(row)open(row);}
async function startDesk(kind:string){deskReturnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;deskCreator.value=kind;await nextTick();deskDialog.value?.querySelector<HTMLButtonElement>('.modal-close')?.focus();}
function closeDesk(){deskCreator.value='';nextTick(()=>deskReturnFocus?.focus());}
async function savedDesk(resource:string){const targetTenant=tenant.value;closeDesk();close();const version=detailVersion;emit('updated');await load(true);if(tenant.value!==targetTenant||detailVersion!==version||selected.value)return;const [type]=resource.split(':');const row=snapshot.value?.resources?.[type]?.find((item:Item)=>item.ref===resource);if(row){selectKind(type);open(row);}}
async function startSchedule(){scheduleReturnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;scheduleCreator.value=true;await nextTick();scheduleDialog.value?.querySelector<HTMLButtonElement>('.modal-close')?.focus();}
function closeSchedule(){scheduleCreator.value=false;nextTick(()=>scheduleReturnFocus?.isConnected&&scheduleReturnFocus.focus());}
async function savedSchedule(resource:string){const targetTenant=tenant.value;closeSchedule();close();const version=detailVersion;emit('updated');await load(true);if(tenant.value!==targetTenant||detailVersion!==version||selected.value)return;const row=snapshot.value?.resources?.schedule?.find((item:Item)=>item.ref===resource);if(row){selectKind('schedule');open(row);}}
function scheduleKeydown(event:KeyboardEvent){if(!scheduleCreator.value)return;if(event.key==='Escape'){event.stopPropagation();closeSchedule();return;}if(event.key!=='Tab'||!scheduleDialog.value)return;const elements=[...scheduleDialog.value.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary,[tabindex="0"]')].filter(item=>item.getClientRects().length);const first=elements[0],last=elements[elements.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
function savedTable(result:Item){if(!selected.value||selected.value.ref!==result.resource)return;const row={...selected.value,name:result.confirmed_name??selected.value.name};const rows=snapshot.value?.resources?.table??[];const index=rows.findIndex((item:Item)=>item.ref===result.resource);if(index>=0)rows[index]={...rows[index],name:row.name};const stack=[...history.value];open(row);history.value=stack;}
function deskKeydown(event:KeyboardEvent){if(!deskCreator.value)return;if(event.key==='Escape'){event.stopPropagation();closeDesk();return;}if(event.key!=='Tab'||!deskDialog.value)return;const elements=[...deskDialog.value.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),[tabindex="0"]')].filter(item=>item.getClientRects().length);const first=elements[0],last=elements[elements.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
function closeCredential(){credentialCreator.value=false;}
function credentialKeydown(event:KeyboardEvent){if(!credentialCreator.value)return;if(event.key==='Escape'){event.stopPropagation();closeCredential();return;}if(event.key!=='Tab'||!credentialDialog.value)return;const elements=[...credentialDialog.value.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')].filter(item=>item.getClientRects().length);const first=elements[0],last=elements[elements.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
watch(tenant,()=>{credentialCreator.value=false;deskCreator.value='';scheduleCreator.value=false;});
function emptySnapshot(targetTenant:string):Item{return{tenant:props.tenants.find(item=>String(item.id)===targetTenant)??{id:targetTenant,name:'Ambiente selecionado'},resources:Object.fromEntries(kinds.map(item=>[item.id,[]])),capabilities:Object.fromEntries(kinds.map(item=>[item.id,{status:'not_loaded',count:null,reason:null}])),tags:[],warnings:[]};}
function quantity(value:string){const item=snapshot.value?.capabilities?.[value];return item?.status==='not_loaded'?'Consultar':item?.count??'—';}
async function load(refresh=false):Promise<void>{
 if(!tenant.value||!props.connected)return;
 const version=++requestVersion;const targetTenant=tenant.value;const targetKind=kind.value;
 loading.value=true;error.value='';
 if(refresh||String(snapshot.value?.tenant?.id)!==targetTenant)snapshot.value=emptySnapshot(targetTenant);
 const task=catalogQueue.then(async()=>{
  if(version!==requestVersion||!props.connected)return;
  try{
   const result=await props.request(refresh?`/catalog/${targetTenant}?refresh=1`:`/catalog/${targetTenant}/sections/${targetKind}`);
   if(version!==requestVersion)return;
   if(String(result?.tenant?.id)!==targetTenant||(!refresh&&result?.section!==targetKind)||!Array.isArray(result?.resources?.[targetKind])||!result?.capabilities?.[targetKind])throw new Error('A resposta do catálogo não corresponde ao ambiente e à categoria selecionados. Tente novamente.');
   const resources={...snapshot.value?.resources,...result.resources};
   const capabilities={...snapshot.value?.capabilities,...result.capabilities};
   const tags=[...new Set(Object.values(resources).flatMap((items:any)=>items.flatMap((row:Item)=>row.tags??[])))].sort();
   snapshot.value={...result,resources,capabilities,tags};
   if(page.value>pages.value)page.value=pages.value;
  }catch(e){if(version===requestVersion){snapshot.value=emptySnapshot(targetTenant);error.value=(e as Error).message;}}
  finally{if(version===requestVersion)loading.value=false;}
 });
 catalogQueue=task.catch(()=>{});
 await task;
}
function clearImage(){if(image.value)URL.revokeObjectURL(image.value);image.value='';}
async function open(row:Item,remember=false){
 if(remember&&selected.value)history.value.push(selected.value);else if(!remember)history.value=[];
 if(!selected.value)returnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;
 const version=++detailVersion;previewVersion++;clearImage();selected.value=row;detail.value=null;preview.value=null;tab.value='overview';dashboard.value='';detailError.value='';detailLoading.value=true;imageLoading.value=false;dataLoading.value=false;
 await nextTick();dialog.value?.querySelector<HTMLButtonElement>('.modal-close')?.focus();
 try{const result=await props.request(row.kind==='variables'?`/catalog/${tenant.value}/variables/${row.id}`:`/catalog/${tenant.value}/resources/${row.kind}/${row.id}`);if(version!==detailVersion)return;detail.value=result;if(dashboardList.value.length)dashboard.value=String(dashboardList.value[0].id??'');}catch(e){if(version===detailVersion)detailError.value=(e as Error).message;}finally{if(version===detailVersion)detailLoading.value=false;}
}
function back(){const previous=history.value.pop();if(!previous)return;const stack=[...history.value];open(previous);history.value=stack;}
function close(){detailVersion++;previewVersion++;selected.value=null;detail.value=null;history.value=[];clearImage();returnFocus?.focus();returnFocus=null;}
async function project(){if(!selected.value)return;const version=detailVersion;const target=selected.value;creating.value=true;detailError.value='';try{const result=await props.request(`/catalog/${tenant.value}/projects`,'POST',{resource:target.ref});if(version!==detailVersion)return;close();emit('project',result.project.id);}catch(e){if(version===detailVersion)detailError.value=(e as Error).message;}finally{creating.value=false;}}
async function loadImage(){if(!selected.value)return;const version=++previewVersion;const resourceVersion=detailVersion;tab.value='image';imageLoading.value=true;dataLoading.value=false;detailError.value='';clearImage();try{const response=await fetch(appUrl(`/api/catalog/${tenant.value}/apps/${selected.value.id}/image${dashboard.value?'?dashboard='+encodeURIComponent(dashboard.value):''}`),{credentials:'same-origin',headers:{Accept:'image/png'}});if(!response.ok){const result=await response.json().catch(()=>({}));throw new Error(result.message??'Não foi possível gerar a prévia visual.');}const blob=await response.blob();if(version===previewVersion&&resourceVersion===detailVersion)image.value=URL.createObjectURL(blob);}catch(e){if(version===previewVersion&&resourceVersion===detailVersion)detailError.value=(e as Error).message;}finally{if(version===previewVersion)imageLoading.value=false;}}
async function loadData(){if(!selected.value)return;const version=++previewVersion;const resourceVersion=detailVersion;tab.value='data';dataLoading.value=true;imageLoading.value=false;preview.value=null;detailError.value='';try{const result=await props.request(`/catalog/${tenant.value}/apps/${selected.value.id}/preview${dashboard.value?'?dashboard='+encodeURIComponent(dashboard.value):''}`);if(version===previewVersion&&resourceVersion===detailVersion)preview.value=result;}catch(e){if(version===previewVersion&&resourceVersion===detailVersion)detailError.value=(e as Error).message;}finally{if(version===previewVersion)dataLoading.value=false;}}
async function dashboardImage(id:string){dashboard.value=id;await nextTick();loadImage();}
async function handlePublication(resource:string){const match=/^(app|flow):[1-9][0-9]*$/.exec(resource);if(!match)return;const currentTenant=tenant.value;close();const version=detailVersion;await load(true);if(tenant.value!==currentTenant||version!==detailVersion||selected.value)return;const row=(snapshot.value?.resources?.[match[1]]??[]).find((item:Item)=>item.ref===resource);if(row)await open(row);}
function keydown(e:KeyboardEvent){if(!selected.value)return;if(e.key==='Escape'){close();return;}if(e.key!=='Tab')return;const elements=Array.from(dialog.value?.querySelectorAll<HTMLElement>('button:not([disabled]),a[href],input,select,textarea,[tabindex="0"]')??[]).filter(element=>element.getClientRects().length);const first=elements[0];const last=elements[elements.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
onMounted(()=>{window.addEventListener('keydown',keydown);window.addEventListener('keydown',credentialKeydown);window.addEventListener('keydown',deskKeydown);window.addEventListener('keydown',scheduleKeydown);const savedLayout=readPreference('catalog-view');if(savedLayout==='grid'||savedLayout==='list')layout.value=savedLayout;const saved=readPreference('tenant');if(saved&&props.tenants.some(t=>String(t.id)===saved))tenant.value=saved;});
onUnmounted(()=>{requestVersion++;detailVersion++;previewVersion++;clearImage();window.removeEventListener('keydown',keydown);window.removeEventListener('keydown',credentialKeydown);window.removeEventListener('keydown',deskKeydown);window.removeEventListener('keydown',scheduleKeydown);});
</script>

<template>
<div class="content-view catalog-view">
 <div class="page-heading"><div><div class="section-eyebrow">SEUS DADOS, SUAS APLICAÇÕES</div><h1>Catálogo BI</h1><p>Explore o G-Analise e escolha onde quer trabalhar.</p></div><span class="soft-badge"><ShieldCheck :size="15"/> Acesso com as suas permissões</span></div>
 <div v-if="!connected" class="empty-state bordered"><Database :size="36"/><h3>Conecte seu G-Analise BI</h3><p>Seus tenants, aplicações e fontes aparecerão aqui.</p><button class="primary-button" @click="emit('connect')">Configurar conexão <ArrowRight :size="15"/></button></div>
 <template v-else>
  <div class="catalog-tenant-bar"><label><Database :size="18"/><span>Tenant</span><select v-model="tenant" aria-label="Tenant do catálogo" data-tour="catalog-tenant"><option value="">Selecione um tenant</option><option v-for="t in tenants" :key="t.id" :value="String(t.id)">{{t.name}}</option></select></label><span v-if="snapshot?.tenant.read_only" class="catalog-readonly"><LockKeyhole :size="14"/> Somente leitura</span><button class="secondary-button" :disabled="!tenant||loading" @click="load(true)"><RefreshCw :size="15" :class="{spin:loading}"/> Atualizar catálogo</button></div>
  <div v-if="!tenant" class="empty-state bordered"><FolderOpen :size="35"/><h3>Escolha um tenant para começar</h3><p>Você pode consultar aplicações publicadas, sua mesa e as fontes de dados de cada ambiente.</p></div>
  <template v-else-if="snapshot">
   <div v-if="snapshot.tenant.read_only" class="catalog-policy"><ShieldCheck :size="18"/><div><strong>Ambiente protegido para consulta</strong><span>Você pode explorar e visualizar. Alterações, publicações e execuções estão bloqueadas neste tenant.</span></div></div>
   <div class="catalog-stat-grid"><button :class="{active:kind==='app'&&scope==='all'}" @click="selectKind('app')"><LayoutDashboard :size="20"/><span>Aplicações</span><strong :class="{'is-unqueried':snapshot.capabilities.app.status==='not_loaded'}">{{snapshot.capabilities.app.status==='not_loaded'?'Consultar':appStats.all??'—'}}</strong></button><button :class="{active:kind==='app'&&scope==='draft'}" @click="selectKind('app','draft')"><FolderOpen :size="20"/><span>Minha Mesa</span><strong :class="{'is-unqueried':snapshot.capabilities.app.status==='not_loaded'}">{{snapshot.capabilities.app.status==='not_loaded'?'Consultar':appStats.mine??'—'}}</strong></button><button :class="{active:kind==='app'&&scope==='published'}" @click="selectKind('app','published')"><CheckCircle2 :size="20"/><span>Publicadas</span><strong :class="{'is-unqueried':snapshot.capabilities.app.status==='not_loaded'}">{{snapshot.capabilities.app.status==='not_loaded'?'Consultar':appStats.published??'—'}}</strong></button><button @click="selectKind('table')"><Table2 :size="20"/><span>Tabelas</span><strong :class="{'is-unqueried':snapshot.capabilities.table.status==='not_loaded'}">{{quantity('table')}}</strong></button></div>
   <div class="catalog-body"><aside class="catalog-kind-nav" data-tour="catalog-types"><button v-for="item in kinds" :key="item.id" :data-tour="item.id==='writeback'?'catalog-writebacks':undefined" :class="{active:kind===item.id}" @click="selectKind(item.id)"><component :is="item.icon" :size="16"/><span>{{item.label}}</span><small>{{quantity(item.id)}}</small></button></aside>
    <div class="catalog-results" :aria-busy="loading"><div class="catalog-filters"><div class="input-with-icon"><Search :size="16"/><input v-model="search" placeholder="Busque por nome, dashboard ou etiqueta…" aria-label="Buscar no catálogo" data-tour="catalog-search"></div><select v-if="['app','table','flow','writeback'].includes(kind)" v-model="scope" aria-label="Situação do recurso"><option value="all">Todas as situações</option><option value="draft">Minha Mesa</option><option value="published">Publicados</option></select><select v-if="desks.length&&['app','table','flow'].includes(kind)" v-model="desk" aria-label="Mesa do recurso"><option value="">Todas as mesas</option><option v-for="d in desks" :key="d.id" :value="d.id">{{d.name}}</option></select><select v-if="snapshot.tags.length" v-model="tag" aria-label="Etiqueta do recurso"><option value="">Todas as etiquetas</option><option v-for="t in snapshot.tags" :key="t">{{t}}</option></select></div>
     <div class="catalog-result-heading"><h2 ref="resultsHeading" tabindex="-1">{{kinds.find(k=>k.id===kind)?.label}}</h2><button v-if="kind==='flow'&&role!=='viewer'&&!snapshot.tenant.read_only&&capability?.status==='available'&&!loading&&!error" type="button" class="primary-button" data-tour="catalog-create-flow" @click="flowWizardCreator=true"><Database :size="15"/>Novo ETL</button><button v-if="['bi-desk','dw-desk'].includes(kind)&&role!=='viewer'&&!snapshot.tenant.read_only&&capability?.status==='available'&&!loading&&!error" class="primary-button" @click="startDesk(kind)"><FolderOpen v-if="kind==='bi-desk'" :size="15"/><Layers3 v-else :size="15"/>{{kind==='bi-desk'?'Nova mesa de aplicações':'Nova mesa de dados'}}</button><button v-if="kind==='credential'&&role!=='viewer'&&!snapshot.tenant.read_only&&capability?.status==='available'&&!loading&&!error" class="primary-button" @click="credentialCreator=true"><Database :size="15"/>Adicionar nova conexão</button><button v-if="kind==='schedule'&&role!=='viewer'&&!snapshot.tenant.read_only&&capability?.status==='available'&&!loading&&!error" class="primary-button" data-tour="catalog-create-schedule" @click="startSchedule"><CalendarClock :size="15"/>Nova agenda</button><div v-if="capability?.status==='available'" class="catalog-layout-controls" role="group" aria-label="Visualização do catálogo" data-tour="catalog-layout"><button type="button" :aria-pressed="layout==='grid'" aria-label="Exibir em cartões" title="Exibir em cartões" @click="chooseLayout('grid')"><LayoutGrid :size="15"/><span>Cartões</span></button><button type="button" :aria-pressed="layout==='list'" aria-label="Exibir em lista" title="Exibir em lista" @click="chooseLayout('list')"><List :size="15"/><span>Lista</span></button></div><span v-if="loading">Consultando…</span><span v-else-if="capability?.status==='available'&&!error">{{filtered.length}} {{filtered.length===1?'recurso':'recursos'}}</span><span v-else>{{capability?.status==='not_loaded'?'Abra para consultar':'Consulta indisponível'}}</span></div>
     <div v-if="loading" class="catalog-loading" role="status" aria-live="polite"><LoaderCircle :size="26" class="spin"/><h3>Consultando {{kinds.find(item=>item.id===kind)?.label}}</h3><p>Estamos conferindo os recursos desta categoria para sua conta.</p><div class="catalog-skeleton"><i v-for="i in 3" :key="i"></i></div></div>
     <div v-else-if="error" class="catalog-error" role="alert"><AlertCircle :size="23"/><div><strong>Não foi possível carregar esta categoria</strong><p>{{error}}</p><button class="secondary-button" @click="load(false)">Tentar novamente</button></div></div>
     <div v-else-if="capability?.status!=='available'" class="catalog-error compact"><LockKeyhole :size="23"/><div><strong>{{label(capability?.status)}}</strong><p>{{capability?.reason}}</p></div></div>
     <div v-else-if="!filtered.length" class="empty-state bordered"><FolderOpen :size="30"/><h3>{{rows.length?'Nenhum resultado para esses filtros':'Nenhum recurso nesta área'}}</h3><p>{{rows.length?'Tente outro termo ou remova os filtros.':'Os recursos disponíveis para sua conta aparecerão aqui.'}}</p></div>
     <div v-else class="catalog-resource-grid" :class="{'is-list':layout==='list'}"><button v-for="row in visible" :key="row.ref" class="catalog-resource" @click="open(row)"><div class="catalog-resource-head"><span class="project-icon small blue"><component :is="kinds.find(k=>k.id===kind)?.icon??Database" :size="19"/></span><span v-if="row.state" class="catalog-state" :class="row.state">{{label(row.state)}}</span><ArrowUpRight :size="16"/></div><h3>{{row.name}}</h3><p>{{row.description||((row.desk_id&&deskNames[row.desk_id])?deskNames[row.desk_id]:row.state==='draft'?'Aplicação ou recurso da sua mesa':row.ref)}}</p><div class="catalog-tags"><span v-for="t in row.tags.slice(0,3)" :key="t"><Tag :size="10"/>{{t}}</span></div><footer><span v-if="row.contents?.length" class="catalog-desk-counts"><small v-for="content in row.contents" :key="content.kind">{{content.count===null?'—':content.count+(content.complete?'':'+')}} {{({table:'tabelas',flow:'ETLs',writeback:'cadastros',app:'aplicações'} as Record<string,string>)[content.kind]}}</small></span><span v-else-if="row.kind==='app'"><LayoutDashboard :size="13"/>{{row.dashboard_count===null?'Ver dashboards':row.dashboard_count+(row.dashboard_count===1?' dashboard':' dashboards')}}</span><span v-else>{{row.ref}}</span><ChevronRight :size="15"/></footer></button></div>
     <div v-if="!loading&&!error&&pages>1" class="catalog-pagination"><span>Página {{page}} de {{pages}}</span><button class="secondary-button" :disabled="page===1" @click="changePage(page-1)"><ChevronLeft :size="14"/> Anterior</button><button class="secondary-button" :disabled="page===pages" @click="changePage(page+1)">Próxima <ChevronRight :size="14"/></button></div>
    </div>
   </div>
   <p class="catalog-footnote">Cada categoria é consultada ao abrir. <strong>Consultar</strong> indica uma quantidade ainda não carregada. Atualizar catálogo renova o inventário completo.</p>
   <p v-if="!loading&&!error&&snapshot.synced_at" class="catalog-footnote">Atualizado em {{new Date(snapshot.synced_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}} · Brasília. O catálogo inclui os recursos autorizados retornados pelo G-Analise.</p><p v-if="unavailable" class="catalog-footnote">{{unavailable}} áreas não estão disponíveis nesta consulta. Consulte cada área para conferir o motivo.</p><p v-for="warning in snapshot.warnings" :key="warning" class="catalog-footnote">{{warning}}</p>
  </template>
 </template>
 <div v-if="selected" class="modal-backdrop" @click.self="close"><section ref="dialog" class="modal catalog-detail" role="dialog" aria-modal="true" :aria-label="selected.name"><button class="modal-close icon-button" aria-label="Fechar recurso" @click="close"><X :size="19"/></button><button v-if="history.length" class="resource-back" @click="back"><ChevronLeft :size="15"/> Voltar para {{history[history.length-1].name}}</button><div class="catalog-detail-heading"><span class="project-icon blue"><component :is="kinds.find(k=>k.id===selected?.kind)?.icon??Database" :size="23"/></span><div><span>{{selected.ref}}</span><h2>{{detail?.resource.name??selected.name}}</h2><p>{{snapshot?.tenant.name}}<template v-if="detail?.resource.state??selected.state"> · {{label(detail?.resource.state??selected.state)}}</template></p></div></div>
  <div v-if="detailLoading" class="catalog-loading"><LoaderCircle :size="24" class="spin"/><p>Carregando detalhes…</p></div><div v-if="detailError" class="form-error" role="alert"><AlertCircle :size="17"/>{{detailError}}</div>
  <template v-if="detail"><p v-if="detail.resource.description" class="catalog-detail-description">{{detail.resource.description}}</p><div v-if="selected.kind==='app'" class="catalog-preview-controls"><label>Dashboard<select v-model="dashboard" aria-label="Dashboard da aplicação"><option v-if="!dashboardList.length" value="">Principal</option><option v-for="(d,index) in dashboardList" :key="d.id??index" :value="String(d.id??'')">{{d.name}}</option></select></label><button v-if="detail.viewer_available" class="secondary-button" :disabled="imageLoading||dataLoading" @click="tab='live'"><Eye :size="16"/>Prévia interativa</button><button class="secondary-button" :disabled="imageLoading||dataLoading" @click="loadImage"><Image :size="16"/> Prévia visual</button><button class="secondary-button" :disabled="imageLoading||dataLoading" @click="loadData"><Table2 :size="16"/> Conferir dados</button></div>
   <button v-if="tab!=='overview'" class="resource-back" @click="tab='overview'"><ChevronLeft :size="15"/> Voltar aos detalhes</button><BiLiveViewer v-if="tab==='live'&&detail.viewer_available" :key="tenant+':'+selected?.id+':'+dashboard" :tenant="tenant" :app-id="String(selected?.id)" :dashboard="dashboard" :request="request" @fallback="loadImage" @started="emit('viewerSession')"/><div v-else-if="tab==='image'" class="catalog-image-preview"><div v-if="imageLoading" class="catalog-loading"><LoaderCircle :size="25" class="spin"/><p>Gerando a prévia real do dashboard…</p></div><template v-if="image"><img :src="image" alt="Prévia real do dashboard selecionado"><a class="secondary-button" :href="image" :download="selected?.name+'.png'"><Download :size="15"/> Baixar PNG</a></template></div>
   <div v-else-if="tab==='data'" class="catalog-data-preview"><div v-if="dataLoading" class="catalog-loading"><LoaderCircle :size="23" class="spin"/><p>Consultando os dados dos widgets…</p></div><WidgetDataPreview v-for="widget in widgets" :key="widget.widget_id" :widget="widget" :interactive-available="detail.viewer_available===true" :visual-available="true" :busy="imageLoading||dataLoading" @interactive="tab='live'" @visual="loadImage"/><p v-if="preview&&!widgets.length" class="catalog-footnote">A aplicação não retornou widgets para esta prévia.</p></div>
   <BiCredentialActions v-if="selected.kind==='credential'&&role!=='viewer'&&!detail.tenant.read_only" :key="tenant+':'+selected.ref" :tenant="tenant" :tenant-name="detail.tenant.name" :resource="detail.resource" :management="detail.credential_management" :request="request" @updated="emit('updated')" @notice="emit('notice',$event)" @saved="savedCredential"/>
   <p v-if="detail.metadata_complete===false" class="catalog-footnote" role="note">{{detail.metadata_message}}</p><div v-if="tab==='overview'" class="catalog-detail-overview"><div class="catalog-detail-facts"><span v-if="detail.resource.dashboard_count!==null"><strong>{{detail.resource.dashboard_count}}</strong> dashboards</span><span v-if="detail.resource.table_count!==null"><strong>{{detail.resource.table_count}}</strong> tabelas vinculadas</span><span v-if="detail.resource.active!==null"><strong>{{detail.resource.active?'Ativo':'Inativo'}}</strong> estado da agenda/recurso</span></div><div v-if="dashboardList.length" class="catalog-dashboard-list"><h3>Dashboards desta aplicação</h3><button v-for="(d,index) in dashboardList" :key="d.id??index" @click="dashboardImage(String(d.id??''))"><LayoutDashboard :size="17"/><strong>{{d.name}}</strong><span>{{d.widget_count}} widgets</span><ChevronRight :size="15"/></button></div><ResourceInspector :download="download" :tenant="tenant" :resource="detail.resource" :request="request"/><ResourceOverview :overview="detail.overview" :related="detail.related" @open="open($event,true)"/><details class="catalog-technical"><summary>Configuração técnica</summary><pre>{{JSON.stringify(detail.details,null,2)}}</pre></details></div>
   <BiTablePresentationForm v-if="selected.kind==='table'&&role!=='viewer'&&!detail.tenant.read_only" :key="tenant+':'+selected.ref" :tenant="tenant" :tenant-name="detail.tenant.name" :resource="detail.resource" :request="request" @updated="emit('updated')" @notice="emit('notice',$event)" @saved="savedTable"/>
   <BiScheduleRun v-if="selected.kind==='schedule'&&role!=='viewer'&&!detail.tenant.read_only" :key="'load:'+tenant+':'+selected.ref" :tenant="tenant" :tenant-name="detail.tenant.name" :resource="detail.resource" :request="request"/>
   <BiScheduleForm v-if="selected.kind==='schedule'&&role!=='viewer'&&!detail.tenant.read_only" :key="tenant+':'+selected.ref" :tenant="tenant" :tenant-name="detail.tenant.name" :resource="detail.resource" :request="request" @updated="emit('updated')" @notice="emit('notice',$event)" @saved="savedSchedule"/>
   <BiDeskForm v-if="['bi-desk','dw-desk'].includes(selected.kind)&&role!=='viewer'&&!detail.tenant.read_only" :key="tenant+':'+selected.ref" :tenant="tenant" :tenant-name="detail.tenant.name" :kind="selected.kind" :resource="detail.resource" :request="request" @updated="emit('updated')" @notice="emit('notice',$event)" @saved="savedDesk"/>
   <BiManualAction v-if="['app','flow'].includes(selected.kind)&&role!=='viewer'&&!detail.tenant.read_only" :key="tenant+':'+selected.ref" :tenant="tenant" :tenant-name="detail.tenant.name" :resource="detail.resource" :desks="snapshot?.resources?.[selected.kind==='flow'?'dw-desk':'bi-desk']??[]" :management="detail.management" :request="request" @active="manualActionOpen=$event" @updated="emit('updated')" @notice="emit('notice',$event)" @project="close();emit('project',$event)" @deleted="close();load(true)" @published="handlePublication($event)"/>
   <div class="modal-footer"><span v-if="detail.tenant.read_only" class="catalog-readonly"><LockKeyhole :size="14"/> Somente leitura</span><button class="secondary-button" @click="close">Fechar</button><button v-if="!manualActionOpen&&role!=='viewer'&&['app','flow','table','schedule'].includes(selected.kind)" class="primary-button" :disabled="creating" @click="project"><LoaderCircle v-if="creating" :size="16" class="spin"/>{{detail.tenant.read_only?'Abrir projeto de análise':'Trabalhar neste recurso'}}<ArrowRight :size="15"/></button></div>
  </template>
 </section></div>
 <div v-if="scheduleCreator" class="modal-backdrop" @click.self="closeSchedule"><section ref="scheduleDialog" class="modal catalog-detail" role="dialog" aria-modal="true" aria-label="Nova agenda de atualização"><button class="modal-close icon-button" aria-label="Fechar configuração de agenda" @click="closeSchedule"><X :size="19"/></button><BiScheduleForm :key="tenant" :tenant="tenant" :tenant-name="snapshot?.tenant.name??tenant" :request="request" @close="closeSchedule" @updated="emit('updated')" @notice="emit('notice',$event)" @saved="savedSchedule"/></section></div>
 <div v-if="deskCreator" class="modal-backdrop" @click.self="closeDesk"><section ref="deskDialog" class="modal catalog-detail" role="dialog" aria-modal="true" :aria-label="deskCreator==='bi-desk'?'Nova mesa de aplicações':'Nova mesa de dados'"><button class="modal-close icon-button" aria-label="Fechar configuração de mesa" @click="closeDesk"><X :size="19"/></button><BiDeskForm :key="tenant+':'+deskCreator" :tenant="tenant" :tenant-name="snapshot?.tenant.name??tenant" :kind="deskCreator" :request="request" @close="closeDesk" @updated="emit('updated')" @notice="emit('notice',$event)" @saved="savedDesk"/></section></div>
 <div v-if="credentialCreator" class="modal-backdrop" @click.self="closeCredential"><section ref="credentialDialog" class="modal catalog-detail" role="dialog" aria-modal="true" aria-label="Adicionar nova conexão"><button class="modal-close icon-button" aria-label="Fechar configuração de conexão" @click="closeCredential"><X :size="19"/></button><BiCredentialForm :key="tenant" :tenant="tenant" :tenant-name="snapshot?.tenant.name??tenant" :request="request" @close="closeCredential" @updated="emit('updated')" @notice="emit('notice',$event)" @saved="savedCredential"/></section></div>
 <BiFlowWizardDialog v-if="flowWizardCreator" :key="tenant" :tenant="tenant" :tenant-name="snapshot?.tenant.name??tenant" :request="request" @close="flowWizardCreator=false" @updated="emit('updated')" @project="flowWizardCreator=false;emit('project',$event)"/>
</div>
</template>
